import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"插件架构","description":"","frontmatter":{"title":"插件架构"},"headers":[],"relativePath":"zh/guide/plugins.md","filePath":"zh/guide/plugins.md","lastUpdated":0}`),a={name:`zh/guide/plugins.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="_4-插件架构" tabindex="-1">4. 插件架构 <a class="header-anchor" href="#_4-插件架构" aria-label="Permalink to “4. 插件架构”">​</a></h1><h2 id="_4-1-插件的职责" tabindex="-1">4.1 插件的职责 <a class="header-anchor" href="#_4-1-插件的职责" aria-label="Permalink to “4.1 插件的职责”">​</a></h2><p>插件负责封装具体资源或能力，而不是实现一套独立的自愈系统。</p><p>插件可以提供：</p><ul><li>Resource Provider。</li><li>Probe Provider。</li><li>Diagnosis Provider。</li><li>Recovery Action Provider。</li><li>Verification Provider。</li><li>Notification Channel Provider。</li></ul><p>一个插件可以提供多种能力。</p><p>例如 OpenClash 插件可以提供：</p><ul><li>OpenClash 服务资源。</li><li>代理端口探测。</li><li>代理认证验证。</li><li>节点状态诊断。</li><li>节点切换动作。</li><li>服务重启动作。</li><li>节点恢复验证。</li></ul><p>Core Engine 负责判断何时调用这些能力以及是否允许执行。</p><h2 id="_4-2-插件执行模型" tabindex="-1">4.2 插件执行模型 <a class="header-anchor" href="#_4-2-插件执行模型" aria-label="Permalink to “4.2 插件执行模型”">​</a></h2><p>第一版使用：</p><p><strong>Rust Core + 外部可执行插件 + JSON-RPC 2.0 over stdio。</strong></p><p>优势：</p><ul><li>插件崩溃不会直接导致核心进程崩溃。</li><li>插件可以使用不同语言实现。</li><li>不需要立即设计稳定的 Rust 动态库 ABI。</li><li>插件协议可以独立版本化。</li><li>有利于隔离插件生命周期和超时。</li></ul><p>但需要明确：外部进程并不自动构成安全沙箱。插件仍然需要最小权限、受控执行目录、受控环境变量和明确的操作授权。</p><h2 id="_4-3-插件协议" tabindex="-1">4.3 插件协议 <a class="header-anchor" href="#_4-3-插件协议" aria-label="Permalink to “4.3 插件协议”">​</a></h2><p>第一版至少需要：</p><div class="language-text" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>initialize</span></span>
<span class="line"><span>describe_capabilities</span></span>
<span class="line"><span>probe</span></span>
<span class="line"><span>diagnose</span></span>
<span class="line"><span>list_recovery_actions</span></span>
<span class="line"><span>execute_recovery_action</span></span>
<span class="line"><span>verify</span></span>
<span class="line"><span>shutdown</span></span></code></pre></div><p>这些是逻辑操作名称，最终应映射为有版本约束的 JSON-RPC 方法。</p><p>请求必须具有：</p><ul><li>JSON-RPC ID。</li><li>协议版本。</li><li>方法名称。</li><li>参数。</li><li>请求超时。</li><li>关联的 Resource ID。</li><li>必要时关联的 RecoveryRun ID。</li></ul><p>恢复操作必须使用显式操作 ID，并携带参数化输入。禁止把任意用户输入直接拼接到 Shell 命令中。</p><h2 id="_4-4-stdio-的工程要求" tabindex="-1">4.4 stdio 的工程要求 <a class="header-anchor" href="#_4-4-stdio-的工程要求" aria-label="Permalink to “4.4 stdio 的工程要求”">​</a></h2><p>Windows 子进程 stdio 管道可能因为缓冲区被写满而阻塞。实现时必须：</p><ul><li>独立、持续读取 stdout 和 stderr。</li><li>stdout 只用于协议消息。</li><li>stderr 用于插件诊断日志。</li><li>限制单条消息大小。</li><li>限制总缓冲区大小。</li><li>支持分块读取。</li><li>处理不完整的消息。</li><li>处理插件提前退出。</li><li>处理无响应和超时。</li><li>支持请求取消。</li><li>对异常 JSON 和未知方法返回明确错误。</li><li>禁止将 stderr 原样作为协议响应解析。</li></ul><p>建议第一版将单条协议消息限制在 1 MiB 以内，具体值作为可配置的安全上限，并对大型证据采用摘要、截断或分块方式处理。</p><h2 id="_4-5-插件生命周期" tabindex="-1">4.5 插件生命周期 <a class="header-anchor" href="#_4-5-插件生命周期" aria-label="Permalink to “4.5 插件生命周期”">​</a></h2><p>建议采用长生命周期插件进程：</p><ol><li>Custos 启动。</li><li>启动已配置的插件。</li><li>完成协议握手。</li><li>获取能力声明。</li><li>验证协议兼容性。</li><li>接受请求。</li><li>监测插件健康状态。</li><li>插件崩溃时根据策略重启。</li><li>插件无法恢复时，将相关资源标记为无法有效探测或操作。</li><li>记录插件故障并通知。</li></ol><p>插件不应因为每次探测都重新创建进程而产生过高开销。</p><h2 id="_4-6-能力权限" tabindex="-1">4.6 能力权限 <a class="header-anchor" href="#_4-6-能力权限" aria-label="Permalink to “4.6 能力权限”">​</a></h2><p>每项能力应声明：</p><ul><li>只读或修改状态。</li><li>所需权限。</li><li>影响的资源范围。</li><li>是否会中断网络。</li><li>是否会中断远程管理。</li><li>是否支持取消。</li><li>是否幂等。</li><li>是否支持验证。</li><li>可能的失败状态。</li><li>是否有补偿或回滚方法。</li></ul><p>Core Engine 根据配置和策略决定是否执行。</p><p>不能因为插件声明了某个动作，就自动允许它执行。</p><hr><h2 id="插件口径补充-用户裁定-2026-10-29" tabindex="-1">插件口径补充（用户裁定 2026-10-29） <a class="header-anchor" href="#插件口径补充-用户裁定-2026-10-29" aria-label="Permalink to “插件口径补充（用户裁定 2026-10-29）”">​</a></h2><ul><li><strong>一个插件 = 一种资源的完整监控与处理逻辑</strong>：探测、诊断、恢复动作、验证闭环在同一个插件内完成，不留半截。</li><li><strong>插件可以被其他插件依赖</strong>：依赖方向与资源依赖图一致，由 Core Engine 统一解析。</li><li><strong>使用方只需简单配置即可启用</strong>：声明资源类型与参数，不写胶水代码；配置加载遵循 §10 的配置规范。</li></ul><h2 id="集成基础能力与-python-脚本扩展-用户裁定-2026-10-29" tabindex="-1">集成基础能力与 Python 脚本扩展（用户裁定 2026-10-29） <a class="header-anchor" href="#集成基础能力与-python-脚本扩展-用户裁定-2026-10-29" aria-label="Permalink to “集成基础能力与 Python 脚本扩展（用户裁定 2026-10-29）”">​</a></h2><ul><li><strong>集成基础能力</strong>：核心引擎内置常见资源（服务、进程、磁盘、网络连通性等）的基础适配，开箱即用——基础场景不需要任何插件开发。</li><li><strong>Python 脚本扩展（双向）</strong>： <ul><li>出向：核心功能经 PyO3 绑定可被 Python 脚本调用；</li><li>入向：自定义探测与恢复动作可以用 Python 脚本编写，由核心按插件契约加载执行（超时、权限、预算同插件口径）。</li></ul></li></ul>`,40)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};